/**
 * npm run test:benches -- partyContext --output-dir <new directory>
 * Synthetic JSON and pure functions only. No DB, model, environment settings or live data.
 * Expectations are handwritten from U0 6-1..6-5 and 8-4, not generated by the builder.
 */
import assert from 'node:assert/strict';
import fs from 'node:fs';
import path from 'node:path';
import { fileURLToPath } from 'node:url';
import { buildPartyContext, renderPartyContextSections, PartyContextOverflowError, type PartyContextInput, type PartyCard } from '../apps/server/src/prompt/partyContext.ts';
import { estimateTokens } from '../apps/server/src/prompt/tokens.ts';

let checks = 0;
let assertions = 0;
const equal = (a: unknown, b: unknown) => { assertions++; assert.deepEqual(a, b); };
const truth = (value: unknown, message?: string) => { assertions++; assert.ok(value, message); };
const throws = (fn: () => unknown, predicate: (e: unknown) => boolean) => { assertions++; assert.throws(fn, predicate); };
function t(name: string, fn: () => void) {
  const before = assertions; fn(); assert.ok(assertions > before, 'test must assert');
  console.log(`ok ${++checks} ${name}`);
}
const fixtures = path.join(path.dirname(fileURLToPath(import.meta.url)), 'fixtures/party-u1');
const setting = fs.readFileSync(path.join(fixtures, 'story-setting.txt'), 'utf8');
const cards = JSON.parse(fs.readFileSync(path.join(fixtures, 'cast-17.json'), 'utf8')) as Record<string, PartyCard>;
const minor = JSON.parse(fs.readFileSync(path.join(fixtures, 'minor-cast.json'), 'utf8'));
const input = (patch: Partial<PartyContextInput> = {}): PartyContextInput => ({
  storySnapshot: { setting, minorCast: minor }, cards, allowedSpeakerIds: ['actor-01'],
  presentIds: Object.keys(cards), sceneState: '確定 STATE_CANARY', items: [], requestRecipients: ['user', 'actor-01'],
  budget: { inputLimitTokens: 12000, outputReserveTokens: 500, calibration: 1 }, estimate: estimateTokens, ...patch,
});
const diagnostic = (r: ReturnType<typeof buildPartyContext>, key: string) => r.diagnostics.sections.find((d) => d.key === key);

t('setting retains all canaries and the entire frozen string', () => {
  const r = buildPartyContext(input());
  equal(r.sections.find((s) => s.key === 'setting')?.text, setting);
  for (const canary of ['SETTING_HEAD_CANARY', 'SETTING_MID_CANARY', 'SETTING_TAIL_CANARY']) truth(renderPartyContextSections(r.sections).includes(canary));
  truth(estimateTokens(setting) >= 2000 && estimateTokens(setting) <= 2200);
});
t('non-speaking present actors have only names and IDs, never detailed cards', () => {
  const r = buildPartyContext(input());
  const all = JSON.stringify(r);
  truth(all.includes('SCN_actor-01'));
  truth(all.includes('DETAIL_actor-01'));
  for (const id of Object.keys(cards).filter((id) => id !== 'actor-01')) {
    equal(all.includes(`SCN_${id}`), false); equal(all.includes(`DETAIL_${id}`), false);
    truth(r.sections.find((s) => s.key === 'roster')?.text.includes(`${cards[id].name} [${id}]`));
  }
});
t('priority order is state, roster, setting, approved card, minor prefix, permitted item', () => {
  const r = buildPartyContext(input({ items: [{ id: 'public-note', kind: 'knowledge', text: 'PUBLIC_ITEM', allowedRecipients: ['user', 'actor-01'] }] }));
  equal(r.sections.map((s) => s.key), ['scene', 'roster', 'setting', 'card:actor-01', 'minor:0', 'minor:1', 'minor:2', 'minor:3', 'minor:4', 'item:public-note']);
  equal(r.sections[0].text, '確定 STATE_CANARY');
});
t('exact required budget succeeds; one short and setting-only overflow return no sections', () => {
  const base = input({ storySnapshot: { setting, minorCast: [] } });
  const complete = buildPartyContext(base);
  const cost = estimateTokens(renderPartyContextSections(complete.sections));
  equal(complete.diagnostics.totalEstimatedTokens, cost);
  equal(complete.sections.reduce((n, s) => n + s.estTokens, 0), cost);
  equal(buildPartyContext({ ...base, budget: { ...base.budget, inputLimitTokens: cost } }).diagnostics.totalEstimatedTokens, cost);
  throws(() => buildPartyContext({ ...base, budget: { ...base.budget, inputLimitTokens: cost - 1 } }), (e) => {
    truth(e instanceof PartyContextOverflowError);
    equal((e as PartyContextOverflowError).shortfallTokens, 1);
    equal('sections' in (e as object), false);
    return (e as PartyContextOverflowError).code === 'party_context_overflow';
  });
  throws(() => buildPartyContext(input({ presentIds: [], allowedSpeakerIds: [], sceneState: '', storySnapshot: { setting, minorCast: [] }, budget: { inputLimitTokens: 1, outputReserveTokens: 500, calibration: 1 } })), (e) => e instanceof PartyContextOverflowError && !('sections' in e));
});
t('minor cast is a whole prefix; after the third misses, later small entries stay omitted', () => {
  const base = input({ storySnapshot: { setting: '', minorCast: ['첫째', '둘째', '긴 셋째 '.repeat(200), '넷', '다섯'] } });
  const firstTwo = buildPartyContext({ ...base, storySnapshot: { setting: '', minorCast: ['첫째', '둘째'] } });
  const limit = estimateTokens(renderPartyContextSections(firstTwo.sections));
  const r = buildPartyContext({ ...base, budget: { ...base.budget, inputLimitTokens: limit } });
  equal(r.sections.filter((s) => s.key.startsWith('minor:')).map((s) => s.key), ['minor:0', 'minor:1']);
  for (const i of [0, 1]) equal(diagnostic(r, `minor:${i}`)?.status, 'included_full');
  for (const i of [2, 3, 4]) { equal(diagnostic(r, `minor:${i}`)?.status, 'omitted'); equal(diagnostic(r, `minor:${i}`)?.reason, 'budget'); }
});
t('recipient subset and output-recipient union exclude secret text from sections and diagnostics', () => {
  const item = { id: 'private-A', kind: 'memory', text: 'ONLY_A_SECRET_CANARY', allowedRecipients: ['A'] };
  truth(JSON.stringify(buildPartyContext(input({ items: [item], requestRecipients: ['A'] }))).includes(item.text));
  const denied = buildPartyContext(input({ items: [item], requestRecipients: ['user', 'A'] }));
  equal(JSON.stringify(denied).includes(item.text), false);
  equal(diagnostic(denied, 'item:private-A')?.reason, 'not_permitted');
  const whisper = { id: 'whisper', kind: 'knowledge', text: 'USER_A_WHISPER_CANARY', allowedRecipients: ['user', 'A'] };
  const merged = buildPartyContext(input({ items: [whisper], requestRecipients: ['user', 'A', 'B'] }));
  equal(JSON.stringify(merged).includes(whisper.text), false);
  equal(diagnostic(merged, 'item:whisper')?.reason, 'not_permitted');
});
t('empty setting and scenario emit omission diagnostics without empty sections', () => {
  const r = buildPartyContext(input({ storySnapshot: { setting: '', minorCast: [] }, cards: { ...cards, 'actor-01': { ...cards['actor-01'], scenario: '' } } }));
  equal(r.sections.some((s) => s.key === 'setting'), false);
  equal(diagnostic(r, 'setting')?.reason, 'empty');
  equal(diagnostic(r, 'card:actor-01:scenario')?.reason, 'empty');
  truth(r.sections.every((s) => s.text.trim().length > 0));
});
t('same inputs give identical bytes, preserve input, and account for calibration', () => {
  const i = input(); const before = JSON.stringify(i);
  equal(JSON.stringify(buildPartyContext(i)), JSON.stringify(buildPartyContext(i)));
  equal(JSON.stringify(i), before);
  const r = buildPartyContext({ ...i, budget: { ...i.budget, calibration: 1.5 } });
  equal(r.diagnostics.totalEstimatedTokens, estimateTokens(renderPartyContextSections(r.sections), 1.5));
});
t('identical display names are selected by ID, and multi-word names are preserved', () => {
  equal(cards['actor-01'].name, cards['actor-02'].name);
  const r = buildPartyContext(input({ allowedSpeakerIds: ['actor-02', 'actor-03'] }));
  equal(r.sections.filter((s) => s.key.startsWith('card:')).map((s) => s.sourceIds), [['actor-02'], ['actor-03']]);
  const all = JSON.stringify(r);
  truth(all.includes('SCN_actor-02')); truth(all.includes('미라 베일'));
  equal(all.includes('SCN_actor-01'), false);
});
t('invalid budgets and unknown card IDs cannot produce partial output', () => {
  throws(() => buildPartyContext(input({ budget: { inputLimitTokens: -1, outputReserveTokens: 500, calibration: 1 } })), (e) => e instanceof RangeError);
  throws(() => buildPartyContext(input({ allowedSpeakerIds: ['unknown'] })), (e) => e instanceof TypeError);
  throws(() => buildPartyContext(input({ requestRecipients: [] })), (e) => e instanceof TypeError);
});
assert.ok(checks > 0 && assertions > 0);
